#include "framework/stm32_hal_ports.hpp"
namespace fw::bsp{namespace{Error map(HAL_StatusTypeDef s){return s==HAL_OK?Error::Ok:s==HAL_TIMEOUT?Error::Timeout:s==HAL_BUSY?Error::Busy:Error::Io;}Result<void>result(HAL_StatusTypeDef s){auto e=map(s);return e==Error::Ok?Result<void>::success():Result<void>::failure(e);}}
Result<std::size_t>Stm32UartPort::write(const std::uint8_t*d,std::size_t n,TransferMode m,std::uint32_t t){if(!d||!n||n>65535)return Result<std::size_t>::failure(Error::InvalidArgument);auto*p=const_cast<std::uint8_t*>(d);HAL_StatusTypeDef s=m==TransferMode::Blocking?HAL_UART_Transmit(&h_,p,n,t):m==TransferMode::Interrupt?HAL_UART_Transmit_IT(&h_,p,n):HAL_UART_Transmit_DMA(&h_,p,n);auto e=map(s);return e==Error::Ok?Result<std::size_t>::success(n):Result<std::size_t>::failure(e);}
Result<void>Stm32I2cPort::write(std::uint16_t a,const std::uint8_t*d,std::size_t n,TransferMode m,std::uint32_t t){if(!d||!n||a>127||n>65535)return Result<void>::failure(Error::InvalidArgument);auto*p=const_cast<std::uint8_t*>(d);if(m==TransferMode::Blocking)return result(HAL_I2C_Master_Transmit(&h_,a<<1,p,n,t));if(m==TransferMode::Dma)return result(HAL_I2C_Master_Transmit_DMA(&h_,a<<1,p,n));return Result<void>::failure(Error::Unsupported);}
Result<void>Stm32I2cPort::read(std::uint16_t a,std::uint8_t*d,std::size_t n,TransferMode m,std::uint32_t t){if(!d||!n||a>127||n>65535)return Result<void>::failure(Error::InvalidArgument);if(m==TransferMode::Blocking)return result(HAL_I2C_Master_Receive(&h_,a<<1,d,n,t));if(m==TransferMode::Dma)return result(HAL_I2C_Master_Receive_DMA(&h_,a<<1,d,n));return Result<void>::failure(Error::Unsupported);}
Result<void>Stm32CanPort::transmit(std::uint32_t id,bool ext,const std::uint8_t*d,std::uint8_t n,TransferMode m,std::uint32_t t){if(!d||n>8)return Result<void>::failure(Error::InvalidArgument);CAN_TxHeaderTypeDef h{};h.IDE=ext?CAN_ID_EXT:CAN_ID_STD;h.RTR=CAN_RTR_DATA;h.DLC=n;if(ext)h.ExtId=id;else h.StdId=id;uint32_t box;HAL_StatusTypeDef s;if(m==TransferMode::Interrupt)s=HAL_CAN_AddTxMessage(&h_,&h,const_cast<std::uint8_t*>(d),&box);else if(m==TransferMode::Blocking){uint32_t start=HAL_GetTick();while(!HAL_CAN_GetTxMailboxesFreeLevel(&h_)){if(HAL_GetTick()-start>=t)return Result<void>::failure(Error::Timeout);}s=HAL_CAN_AddTxMessage(&h_,&h,const_cast<std::uint8_t*>(d),&box);}else return Result<void>::failure(Error::Unsupported);return result(s);}
Result<void>Stm32TimerPort::startPeriodic(std::uint32_t period,void(*cb)(void*),void*ctx){if(!period||!cb)return Result<void>::failure(Error::InvalidArgument);callback_=cb;context_=ctx;auto r=result(HAL_TIM_Base_Start_IT(&h_));if(!r){callback_=nullptr;context_=nullptr;}return r;}void Stm32TimerPort::stop(){HAL_TIM_Base_Stop_IT(&h_);callback_=nullptr;context_=nullptr;}void Stm32TimerPort::onPeriodElapsed(TIM_HandleTypeDef* h){if(h==&h_&&callback_)callback_(context_);}
}
